SD := Client.GetDocumentByPath('C:\Users\makarlistkov\Documents\Work\Engineering\FPGA-COURSE-WORK\ARTIX\ARTIX\libraries\HR911130A\new\HR911130A.SchLib');
if SD <> Nil then begin

  L := Nil; if SD <> Nil then L := SchServer.GetSchDocumentByPath('C:\Users\makarlistkov\Documents\Work\Engineering\FPGA-COURSE-WORK\ARTIX\ARTIX\libraries\HR911130A\new\HR911130A.SchLib');
  if L <> Nil then begin
    C := Nil; LI := L.SchLibIterator_Create;
    LI.AddFilter_ObjectSet(MkSet(eSchComponent)); LC := LI.FirstSchObject;
    while LC <> Nil do begin if LC.LibReference = 'HR911130A' then C := LC; LC := LI.NextSchObject; end;
    L.SchIterator_Destroy(LI);
    if C <> Nil then begin
      LogStep('select exact library component');
      if L.CurrentSchComponent.LibReference <> 'HR911130A' then L.CurrentSchComponent := C;
      C := L.CurrentSchComponent;
      if C.LibReference = 'HR911130A' then begin
        LogStep('save editor checkpoint'); if SD.DoFileSave('') then ResultText:='{"saved":true}' else ResultText:='{"error":"CHECKPOINT_FAILED"}';
      end else ResultText := '{"error":"WRONG_ACTIVE_COMPONENT"}';
    end else ResultText := '{"error":"COMPONENT_NOT_FOUND"}';
  end else ResultText := '{"error":"NO_LIBRARY"}';
end else ResultText := '{"error":"DOCUMENT_NOT_OPEN"}';
